import itertools

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            vec = (dr, dc)
            if vec in vectors:
                return False
            vectors.add(vec)
    return len(vectors) == n*(n-1)//2

fixed = {2: 3}
positions = [0,1,2,3,4]
rows = [0,1,2,3,4]
available_rows = [r for r in rows if r not in fixed.values()]
available_pos = [p for p in positions if p not in fixed]

for perm_rows in itertools.permutations(available_rows):
    perm = [0]*5
    for pos, row in fixed.items():
        perm[pos] = row
    idx = 0
    for pos in available_pos:
        perm[pos] = perm_rows[idx]
        idx += 1
    if is_costas(perm):
        print(perm)
        break
else:
    print("None found")
